CREATE TABLE `general_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `site_name` varchar(255) DEFAULT NULL,
  `cur_text` varchar(255) DEFAULT NULL,
  `cur_sym` varchar(255) DEFAULT NULL,
  `payment_cur_text` varchar(255) DEFAULT NULL,
  `email_from` varchar(255) DEFAULT NULL,
  `email_from_name` varchar(255) DEFAULT NULL,
  `email_template` text DEFAULT NULL,
  `sms_template` text DEFAULT NULL,
  `sms_from` varchar(255) DEFAULT NULL,
  `push_title` varchar(255) DEFAULT NULL,
  `push_template` text DEFAULT NULL,
  `plan_api` varchar(255) DEFAULT NULL,
  `currency_api_key` varchar(255) DEFAULT NULL,
  `base_color` varchar(255) DEFAULT NULL,
  `secondary_color` varchar(255) DEFAULT NULL,
  `mail_config` text DEFAULT NULL,
  `sms_config` text DEFAULT NULL,
  `firebase_config` text DEFAULT NULL,
  `global_shortcodes` text DEFAULT NULL,
  `kv` tinyint(1) DEFAULT 0,
  `ev` tinyint(1) DEFAULT 0,
  `en` tinyint(1) DEFAULT 0,
  `sv` tinyint(1) DEFAULT 0,
  `sn` tinyint(1) DEFAULT 0,
  `pn` tinyint(1) DEFAULT 0,
  `force_ssl` tinyint(1) DEFAULT 0,
  `in_app_payment` tinyint(1) DEFAULT 0,
  `maintenance_mode` tinyint(1) DEFAULT 0,
  `secure_password` tinyint(1) DEFAULT 0,
  `agree` tinyint(1) DEFAULT 0,
  `multi_language` tinyint(1) DEFAULT 0,
  `registration` tinyint(1) DEFAULT 0,
  `referral_amount` decimal(18,8) DEFAULT 0.00000000,
  `active_template` varchar(255) DEFAULT NULL,
  `socialite_credentials` text DEFAULT NULL,
  `last_cron` timestamp NULL DEFAULT NULL,
  `available_version` varchar(255) DEFAULT NULL,
  `system_customized` tinyint(1) DEFAULT 0,
  `paginate_number` int(11) DEFAULT 20,
  `currency_format` int(11) DEFAULT 1,
  `config_progress` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
